import{c as t,Q as e,j as i,m as a}from"./chunks/framework.BXc4yaFE.js";const k=JSON.parse('{"title":"Session Insights v2 — Claude Code 深度研究盲點補足（2026-06-07）","description":"","frontmatter":{"title":"Session Insights v2 — Claude Code 深度研究盲點補足（2026-06-07）","date":"2026-06-07T00:00:00.000Z","parent-report":"2026-06-07-claude-code-deep-practices-v2.md","type":"meta-reflection","version":2},"headers":[],"relativePath":"research/reports/2026-06-07-session-insights-v2.md","filePath":"research/reports/2026-06-07-session-insights-v2.md","lastUpdated":1780842316000}'),r={name:"research/reports/2026-06-07-session-insights-v2.md"};function n(o,s,l,h,d,p){return e(),i("div",null,[...s[0]||(s[0]=[a(`<h1 id="session-insights-v2-—-盲點補足研究的-meta-lessons" tabindex="-1">Session Insights v2 — 盲點補足研究的 Meta-lessons <a class="header-anchor" href="#session-insights-v2-—-盲點補足研究的-meta-lessons" aria-label="Permalink to &quot;Session Insights v2 — 盲點補足研究的 Meta-lessons&quot;">​</a></h1><h2 id="_1-本次研究方法改進" tabindex="-1">1. 本次研究方法改進 <a class="header-anchor" href="#_1-本次研究方法改進" aria-label="Permalink to &quot;1. 本次研究方法改進&quot;">​</a></h2><h3 id="相比-v1-的搜尋策略改進" tabindex="-1">相比 v1 的搜尋策略改進 <a class="header-anchor" href="#相比-v1-的搜尋策略改進" aria-label="Permalink to &quot;相比 v1 的搜尋策略改進&quot;">​</a></h3><p><strong>v1 盲點</strong> → <strong>v2 修正方式</strong>：</p><table tabindex="0"><thead><tr><th>v1 盲點</th><th>v2 做法</th><th>效果</th></tr></thead><tbody><tr><td>A：企業案例低曝光</td><td>搜尋企業博客 + LinkedIn + VentureBeat</td><td>找到 TELUS/Zapier/Anthropic 內部數據</td></tr><tr><td>B：負面案例難找</td><td>明確加入 failure/abandoned/retrospective 關鍵詞</td><td>找到 6,852 session 崩潰數據 + Anthropic postmortem</td></tr><tr><td>C：數字可信度未分級</td><td>在 scratch 格式中強制標 [學術]/[企業自述]/[個人宣稱]</td><td>所有數字在報告中都帶可信度標記</td></tr><tr><td>D：時間序列缺失</td><td>搜尋 &quot;2025 vs 2026 paradigm shift&quot; + Sean Moran</td><td>找到三個基礎設施改變的縱向分析</td></tr></tbody></table><h3 id="新發現角度-v1-完全沒有" tabindex="-1">新發現角度（v1 完全沒有） <a class="header-anchor" href="#新發現角度-v1-完全沒有" aria-label="Permalink to &quot;新發現角度（v1 完全沒有）&quot;">​</a></h3><ol><li><strong>安全 CVE 軌跡</strong>：三個 CVE（2025-59536/2026-21852/2025-54794）揭示 pre-trust window 是架構性漏洞，不是配置問題</li><li><strong>架構確定性比例</strong>：98.4% 確定性基礎設施（arXiv 學術數據）——這個數字改變了對 CLAUDE.md 作為安全機制的認知</li><li><strong>Self-evolving harness</strong>：LobeHub L1→L4 演化梯度，75%→95% 成功率（生產級實測）</li><li><strong>Effort 量化矩陣</strong>：high vs xhigh 的具體 ROI（high=93/100 vs xhigh=95/100，成本差 4x）</li></ol><hr><h2 id="_2-對-zeuik-harness-的新發現" tabindex="-1">2. 對 Zeuik Harness 的新發現 <a class="header-anchor" href="#_2-對-zeuik-harness-的新發現" aria-label="Permalink to &quot;2. 對 Zeuik Harness 的新發現&quot;">​</a></h2><h3 id="發現-1-claude-md-的安全角色誤解-p0-級" tabindex="-1">發現 1：CLAUDE.md 的安全角色誤解（P0 級） <a class="header-anchor" href="#發現-1-claude-md-的安全角色誤解-p0-級" aria-label="Permalink to &quot;發現 1：CLAUDE.md 的安全角色誤解（P0 級）&quot;">​</a></h3><p><strong>arXiv 2604.14228 的關鍵區分</strong>：CLAUDE.md 是 <strong>user context</strong>，非 system prompt。這意味著：</p><ul><li>CLAUDE.md 規則是機率性遵從（~70%），hooks 才是 100% 確定性執行</li><li>把安全關鍵規則（如禁止 rm -rf、阻止敏感檔案讀取）放在 CLAUDE.md 是設計錯誤</li><li>這與 Zeuik harness 的「hooks 是確定性 gate」原則一致，但可能還有規則仍在 CLAUDE.md 而非 hooks</li></ul><p><strong>驗證行動</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 稽核哪些規則在 CLAUDE.md vs hooks</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MUST NOT\\|never\\|block\\|禁止\\|不得&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .claude/rules/core.md</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安全關鍵的規則 → 遷移到 hooks</span></span></code></pre></div><h3 id="發現-2-skill-激活率問題-已有-hooks-的-zeuik-harness-可直接修復" tabindex="-1">發現 2：Skill 激活率問題（已有 hooks 的 Zeuik harness 可直接修復） <a class="header-anchor" href="#發現-2-skill-激活率問題-已有-hooks-的-zeuik-harness-可直接修復" aria-label="Permalink to &quot;發現 2：Skill 激活率問題（已有 hooks 的 Zeuik harness 可直接修復）&quot;">​</a></h3><p><strong>Alex Opalic 的數據</strong>：自然觸發 ~20%，UserPromptSubmit hook 注入後 ~84%。</p><p><strong>Zeuik harness 現狀</strong>：RESOLVER.md 存在，但 skill 是否在 84% 案例中被激活？</p><p><strong>驗證行動</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 統計近 10 次 skill 呼叫 vs 應該觸發但未觸發的次數</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Skill&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/logs/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.jsonl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;需要其他方式統計&quot;</span></span></code></pre></div><p><strong>修復方案</strong>：在 settings.json 加 UserPromptSubmit hook 注入 MANDATORY SKILL ACTIVATION 評估邏輯（詳見 source-7）。</p><h3 id="發現-3-cve-2025-59536-供應鏈攻擊向量-安全" tabindex="-1">發現 3：CVE-2025-59536 供應鏈攻擊向量（安全） <a class="header-anchor" href="#發現-3-cve-2025-59536-供應鏈攻擊向量-安全" aria-label="Permalink to &quot;發現 3：CVE-2025-59536 供應鏈攻擊向量（安全）&quot;">​</a></h3><p><strong>攻擊路徑</strong>：惡意 repo clone → .claude/settings.json 中的 hooks 在 trust dialog 前執行 → RCE</p><p><strong>Zeuik harness 防護狀態</strong>：</p><ul><li>是否稽核過 .claude/settings.json 的 hooks 來源？</li><li>是否對外部 repo 的 config 變更做等同 code review？</li></ul><p><strong>驗證行動</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 確認 hooks 都指向受信任的腳本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .claude/settings.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import json,sys; d=json.load(sys.stdin); print(json.dumps(d.get(&#39;hooks&#39;,{}), indent=2))&quot;</span></span></code></pre></div><h3 id="發現-4-dynamic-workflows-三大失敗模式-→-zeuik-harness-的-unverified-success-閘門設計印證" tabindex="-1">發現 4：Dynamic Workflows 三大失敗模式 → Zeuik harness 的 unverified_success 閘門設計印證 <a class="header-anchor" href="#發現-4-dynamic-workflows-三大失敗模式-→-zeuik-harness-的-unverified-success-閘門設計印證" aria-label="Permalink to &quot;發現 4：Dynamic Workflows 三大失敗模式 → Zeuik harness 的 unverified_success 閘門設計印證&quot;">​</a></h3><p><strong>@trq212 記錄的三大失敗模式</strong>：</p><ol><li>Agentic laziness（20/50 項就宣告完成）</li><li>Self-preferential bias（偏好自己結論的驗證者）</li><li>Goal drift（compact 後「不要做 X」被丟失）</li></ol><p><strong>Zeuik harness 對應機制</strong>（core.md TEST 節）：</p><ul><li>unverified_success 閘門解決了 #1（subagent 自報「成功」≠ verified）</li><li>adjudicate 主對話親跑解決了 #2（絕不經 sub-agent 中介）</li><li>RECORD 階段的 checkpoint 解決了 #3</li></ul><p>→ <strong>結論</strong>：Zeuik harness 的設計與社群最新研究高度一致，是獨立收斂的驗證。</p><hr><h2 id="_3-搜尋策略改進建議-供下次研究" tabindex="-1">3. 搜尋策略改進建議（供下次研究） <a class="header-anchor" href="#_3-搜尋策略改進建議-供下次研究" aria-label="Permalink to &quot;3. 搜尋策略改進建議（供下次研究）&quot;">​</a></h2><h3 id="本次仍有的盲點" tabindex="-1">本次仍有的盲點 <a class="header-anchor" href="#本次仍有的盲點" aria-label="Permalink to &quot;本次仍有的盲點&quot;">​</a></h3><p><strong>新盲點 E：MCP 安全細節</strong> 本次只找到架構層面的 MCP 安全（gateway 模式），但缺少：</p><ul><li>MCP server 權限最小化實踐</li><li>MCP credential rotation 實務</li><li>多 MCP server 之間的 trust boundary</li></ul><p><strong>新盲點 F：非英語社群</strong> 所有來源均為英語。中文/日語/韓語的 Claude Code 實踐社群可能有不同模式（尤其是企業合規需求）。</p><p><strong>新盲點 G：Prompt Injection 防禦生產實踐</strong> 找到攻擊 CVE，但缺少「生產環境防禦 prompt injection」的具體 harness 設計（input sanitization / allowlist 心智模型的實際實施）。</p><h3 id="三個提高覆蓋率的搜尋技巧" tabindex="-1">三個提高覆蓋率的搜尋技巧 <a class="header-anchor" href="#三個提高覆蓋率的搜尋技巧" aria-label="Permalink to &quot;三個提高覆蓋率的搜尋技巧&quot;">​</a></h3><ol><li><strong>用時間範圍限定搜尋</strong>：加入 <code>after:2026-01-01</code> 過濾器</li><li><strong>GitHub Issues 搜尋</strong>：anthropics/claude-code Issues 包含大量負面案例和 regression 報告</li><li><strong>HN 「Who&#39;s using」thread 搜尋</strong>：<code>site:news.ycombinator.com &quot;Claude Code&quot; show OR ask</code></li></ol><hr><h2 id="_4-數字可信度分級系統-本次實施" tabindex="-1">4. 數字可信度分級系統（本次實施） <a class="header-anchor" href="#_4-數字可信度分級系統-本次實施" aria-label="Permalink to &quot;4. 數字可信度分級系統（本次實施）&quot;">​</a></h2><p>本次研究在 scratch 格式中強制標記來源可信度，最終報告中所有數字都帶標記：</p><table tabindex="0"><thead><tr><th>等級</th><th>標記</th><th>說明</th><th>範例</th></tr></thead><tbody><tr><td>學術</td><td>[學術]</td><td>arXiv / peer-reviewed</td><td>98.4% 確定性基礎設施</td></tr><tr><td>官方</td><td>[官方]</td><td>Anthropic 文件 / postmortem</td><td>三個根本原因時間序</td></tr><tr><td>企業自述</td><td>[企業自述]</td><td>有名有姓的企業數據</td><td>TELUS 500K 工時</td></tr><tr><td>個人宣稱</td><td>[個人宣稱]</td><td>個人 blog / tweet</td><td>Branch8 -72%</td></tr></tbody></table><p><strong>教訓</strong>：收集階段就分級，比報告撰寫後補標記效率高 3x。</p><hr><h2 id="_5-技術決策記錄-本次研究過程" tabindex="-1">5. 技術決策記錄（本次研究過程） <a class="header-anchor" href="#_5-技術決策記錄-本次研究過程" aria-label="Permalink to &quot;5. 技術決策記錄（本次研究過程）&quot;">​</a></h2><h3 id="決策-1-為何選-worktree-而非主-branch" tabindex="-1">決策 1：為何選 worktree 而非主 branch <a class="header-anchor" href="#決策-1-為何選-worktree-而非主-branch" aria-label="Permalink to &quot;決策 1：為何選 worktree 而非主 branch&quot;">​</a></h3><p>原因：</p><ul><li>本次研究涉及 30+ 新文章收錄，commit 量大</li><li>避免與 feature/claude-code-practices-research branch 的現有 32 篇衝突</li><li>符合 core.md「多 session 並行 → 用 worktree」規則</li></ul><h3 id="決策-2-為何不使用-overnight-research-full-20-輪迭代" tabindex="-1">決策 2：為何不使用 overnight-research:full 20 輪迭代 <a class="header-anchor" href="#決策-2-為何不使用-overnight-research-full-20-輪迭代" aria-label="Permalink to &quot;決策 2：為何不使用 overnight-research:full 20 輪迭代&quot;">​</a></h3><p>原因：</p><ul><li>已有 32 篇基礎，本次目標是「補盲點」而非從零開始</li><li>20 輪迭代對補充研究是過度工程（Rule of proportionality）</li><li>選擇 phase-by-phase 手動控制，確保每階段可驗證</li></ul><h3 id="決策-3-為何-session-insights-獨立為一個報告而非附錄" tabindex="-1">決策 3：為何 session insights 獨立為一個報告而非附錄 <a class="header-anchor" href="#決策-3-為何-session-insights-獨立為一個報告而非附錄" aria-label="Permalink to &quot;決策 3：為何 session insights 獨立為一個報告而非附錄&quot;">​</a></h3><p>原因：</p><ul><li>session insights 的目標受眾是「研究者自己」（meta-reflection）</li><li>主報告的目標受眾是「harness 設計者」（可執行建議）</li><li>混在一起會降低兩份文件的可讀性和搜尋效率</li></ul><hr><p><em>meta-reflection v2.0 by research agent | 2026-06-07</em></p>`,59)])])}const u=t(r,[["render",n]]);export{k as __pageData,u as default};
